.darma-loader-darma-b8-cube-3d-spin { --accent: var(--loader-color, #6366f1); --accent-2: var(--loader-secondary-color, #22d3ee); width: var(--loader-size, 84px); height: var(--loader-size, 84px); display: grid; place-items: center; perspective: 600px; }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube { --s: calc(var(--loader-size, 84px) * .52); position: relative; width: var(--s); height: var(--s); transform-style: preserve-3d; animation: darma-loader-darma-b8-cube-3d-spin-cube-spin calc(var(--loader-speed, 1s) * 3) linear infinite; }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span { position: absolute; inset: 0; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 82%, transparent), color-mix(in srgb, var(--accent-2) 82%, transparent)); border: 1px solid color-mix(in srgb, #fff 30%, transparent); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(1) { transform: rotateY(0deg) translateZ(calc(var(--s) / 2)); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(2) { transform: rotateY(90deg) translateZ(calc(var(--s) / 2)); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(3) { transform: rotateY(180deg) translateZ(calc(var(--s) / 2)); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(4) { transform: rotateY(270deg) translateZ(calc(var(--s) / 2)); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(5) { transform: rotateX(90deg) translateZ(calc(var(--s) / 2)); }
.darma-loader-darma-b8-cube-3d-spin .darma-loader-darma-b8-cube-3d-spin__cube span:nth-child(6) { transform: rotateX(-90deg) translateZ(calc(var(--s) / 2)); }
@keyframes darma-loader-darma-b8-cube-3d-spin-cube-spin { 0% { transform: rotateX(-24deg) rotateY(0deg); } 100% { transform: rotateX(-24deg) rotateY(360deg); } }

